import sys
import json


def solve(digits):
    if not digits:
        return []
    keyboard = ('', '', 'abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz')
    path = [''] * len(digits)
    answer = []

    def visit(position):
        if position == len(digits):
            answer.append(''.join(path))
            return
        for letter in keyboard[int(digits[position])]:
            path[position] = letter
            visit(position + 1)

    visit(0)
    return answer


def main():
    digits = sys.stdin.readline().rstrip("\r\n")
    answer = solve(digits)
    print(json.dumps(answer, ensure_ascii=False))


if __name__ == "__main__":
    main()

import sys
from functools import cache


def solve(nums):
    @cache
    def best(last):
        # best(last) 是前 last + 1 间房屋能够取得的最大金额。
        if last < 0:
            return 0
        skip = best(last - 1)
        take = nums[last] + best(last - 2)
        return max(skip, take)

    return best(len(nums) - 1)


def main():
    n = int(sys.stdin.readline())
    nums = list(map(int, sys.stdin.readline().split()))
    answer = solve(nums)
    print(answer)


