import sys


def solve(nums, target):
    difference = sum(nums) - abs(target)
    if difference < 0 or difference % 2 != 0:
        return 0
    capacity = difference // 2
    ways = [0] * (capacity + 1)
    ways[0] = 1
    for value in nums:
        # 倒序确保每个位置只选一次；value 为 0 时会把方案数翻倍。
        for total in range(capacity, value - 1, -1):
            ways[total] += ways[total - value]
    return ways[capacity]


def main():
    n, target = map(int, sys.stdin.readline().split())
    nums = list(map(int, sys.stdin.readline().split()))
    answer = solve(nums, target)
    print(answer)


if __name__ == "__main__":
    main()

import sys


def solve(text1, text2):
    rows, columns = len(text1), len(text2)
    length = [[0] * (columns + 1) for _ in range(rows + 1)]
    # length[i][j] 表示 text1[:i] 与 text2[:j] 的最长公共子序列长度。
    for i in range(1, rows + 1):
        for j in range(1, columns + 1):
            if text1[i - 1] == text2[j - 1]:
                length[i][j] = length[i - 1][j - 1] + 1
            else:
                length[i][j] = max(length[i - 1][j], length[i][j - 1])
    return length[rows][columns]


def main():
    text1 = sys.stdin.readline().rstrip("\r\n")
    text2 = sys.stdin.readline().rstrip("\r\n")
    answer = solve(text1, text2)
    print(answer)


