import sys


def solve(word1, word2):
    rows, columns = len(word1), len(word2)
    distance = [[0] * (columns + 1) for _ in range(rows + 1)]
    for j in range(columns + 1):
        distance[0][j] = j  # 空串变成 word2[:j]，需要插入 j 次。
    for i in range(1, rows + 1):
        distance[i][0] = i
        for j in range(1, columns + 1):
            if word1[i - 1] == word2[j - 1]:
                distance[i][j] = distance[i - 1][j - 1]
            else:
                delete = distance[i - 1][j]
                insert = distance[i][j - 1]
                replace = distance[i - 1][j - 1]
                distance[i][j] = min(delete, insert, replace) + 1
    return distance[rows][columns]


