import sys
from bisect import bisect_left


def solve(nums):
    tails = []
    for value in nums:
        # 找第一个 >= value 的末尾；相等时替换，不会增加长度。
        position = bisect_left(tails, value)
        if position < len(tails):
            tails[position] = value
        else:
            tails.append(value)
    return len(tails)


def main():
    n = int(sys.stdin.readline())
    nums = list(map(int, sys.stdin.readline().split()))
    answer = solve(nums)
    print(answer)


