import sys
from math import inf


def solve(prices, k):
    # state[j] 对应至多买入 j - 1 次；下标 0 留作不可能状态。
    state = [[-inf, -inf] for _ in range(k + 2)]
    for j in range(1, k + 2):
        state[j][0] = 0
    for price in prices:
        # 倒序保证买入时读到的 state[j - 1] 仍属于前一天。
        for j in range(k + 1, 0, -1):
            state[j][0] = max(state[j][0], state[j][1] + price)
            state[j][1] = max(state[j][1], state[j - 1][0] - price)
    return state[k + 1][0]


def main():
    n, k = map(int, sys.stdin.readline().split())
    prices = list(map(int, sys.stdin.readline().split()))
    answer = solve(prices, k)
    print(answer)


if __name__ == "__main__":
    main()

import sys


def solve(s):
    size = len(s)
    longest = [[0] * size for _ in range(size)]
    for left in range(size - 1, -1, -1):
        longest[left][left] = 1
        for right in range(left + 1, size):
            if s[left] == s[right]:
                longest[left][right] = longest[left + 1][right - 1] + 2
            else:
                longest[left][right] = max(longest[left + 1][right], longest[left][right - 1])
    return longest[0][size - 1]


def main():
    s = sys.stdin.readline().rstrip("\r\n")
    answer = solve(s)
    print(answer)


if __name__ == "__main__":
    main()

import sys


def solve(values):
    size = len(values)
    score = [[0] * size for _ in range(size)]
    for left in range(size - 3, -1, -1):
        for right in range(left + 2, size):
            score[left][right] = min(
                score[left][middle] + score[middle][right]
                + values[left] * values[middle] * values[right]
                for middle in range(left + 1, right)
            )
    return score[0][size - 1]


def main():
    n = int(sys.stdin.readline())
    values = list(map(int, sys.stdin.readline().split()))
    answer = solve(values)
    print(answer)


